  "implementation": "def solve(case):
    import json
    payload = case['payload']
    nodes = payload['nodes']
    core_distance = payload['core_distance']
    distances = payload['distances']
    if not isinstance(nodes, list) or not all(isinstance(n, str) for n in nodes):
        raise ValueError('Invalid nodes')
    if not isinstance(core_distance, dict) or set(core_distance.keys()) != set(nodes):
        raise ValueError('Invalid core_distance')
    if not isinstance(distances, list) or len(distances) < 1:
        raise ValueError('Invalid distances')
    n = len(nodes)
    # Build distance lookup
    dist_dict = {}
    for entry in distances:
        if not isinstance(entry, list) or len(entry) != 3:
            raise ValueError('Invalid distance entry')
        u, v, d = entry
        if u not in nodes or v not in nodes:
            raise ValueError('Unknown node in distance')
        key = (u, v) if u < v else (v, u)
        dist_dict[key] = d
    # Prepare edges
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            u = nodes[i]
            v = nodes[j]
            key = (u, v)
            if key not in dist_dict:
                raise ValueError(f'Missing distance between {u} and {v}')
            d = dist_dict[key]
            w = max(core_distance[u], core_distance[v], d)
            edges.append((w, u, v))
    # Sort edges deterministically: by weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    selected = []
    total_weight = 0.0
    for w, u, v in edges:
        if len(selected) == n - 1:
            break
        if union(u, v):
            selected.append([u, v, w])
            total_weight += w
    if len(selected) != n - 1:
        raise ValueError('Graph is disconnected')
    return {'edges': selected, 'total_weight': total_weight}"
